// 2. MOTOR DE CARGA CON LÓGICA DE SUITE 3.0 (EDICIÓN CON DELAYS)
(async function() {
    console.log("%c⏳ ESPERANDO 5 SEGUNDOS ANTES DE INICIAR...", "color: #ff9900; font-weight: bold; font-size: 14px;");
    
    // Espera inicial de 5 segundos
    await new Promise(resolve => setTimeout(resolve, 5000));

    console.log("%c🚀 INICIANDO SOBRESCRITURA (ESTILO SUITE 3.0)...", "color: #007cff; font-weight: bold;");

    // Lógica exacta de getReactApp de la Suite 3.0
    const getReactApp = () => {
        const root = document.querySelector('.App') || document.querySelector('#root');
        if (!root) return null;
        const key = Object.keys(root).find(k => k.startsWith('__react'));
        let fiber = root[key];
        while (fiber) {
            if (fiber.stateNode && typeof fiber.stateNode.setState === 'function' && fiber.stateNode.randomize) {
                return fiber.stateNode;
            }
            fiber = fiber.return;
        }
        return null;
    };

    const app = getReactApp();
    if (!app) {
        console.error("❌ ERROR: React no detectado. Asegúrate de estar en el Builder.");
        return;
    }

    // Comprobamos si ImagesLoaded existe antes de seguir
    if (typeof ImagesLoaded === 'undefined') {
        console.error("❌ ERROR: La variable 'ImagesLoaded' no está definida. Pégala antes de este script.");
        return;
    }

    console.log(`🔍 Procesando ${ImagesLoaded.length} elementos...`);
    let countMemory = 0;
    let countVisual = 0;

    // Buscamos imágenes en TODA la interfaz (Library y Layers)
    const imagenesDOM = document.querySelectorAll('.List.Library img, .List.Layers img, .layers img');

    for (let i = 0; i < ImagesLoaded.length; i++) {
        const item = ImagesLoaded[i];

        // --- APARTADO A: ACTUALIZAR MEMORIA MAESTRA (REACT) ---
        const targetAsset = app.state.assets.find(a => a.prettyName === item.name || a.name === item.name);
        
        if (targetAsset) {
            targetAsset.src = item.data;
            if (targetAsset.img) targetAsset.img.src = item.data; // Para el Canvas

            // HACK DEL VIRTUAL DOM (Extraído de Suite 3.0)
            if (targetAsset.imgEl && targetAsset.imgEl.props) {
                targetAsset.imgEl = Object.assign({}, targetAsset.imgEl, {
                    props: Object.assign({}, targetAsset.imgEl.props, {
                        src: item.data
                    })
                });
            }
            countMemory++;
        }

        // --- APARTADO B: ACTUALIZAR CAPAS ACTIVAS (CANVAS Y LISTA) ---
        if (app.state.layers) {
            app.state.layers.forEach(layer => {
                if (layer.asset && (layer.asset.prettyName === item.name || layer.asset.name === item.name)) {
                    layer.asset.src = item.data;
                    if (layer.asset.img) layer.asset.img.src = item.data;
                }
            });
        }

        // --- APARTADO C: ACTUALIZAR ELEMENTOS VISUALES (DOM) ---
        const elementosAActualizar = Array.from(imagenesDOM).filter(img =>
            img.alt === item.name || (img.parentElement && img.parentElement.title === item.name)
        );

        elementosAActualizar.forEach(imgElement => {
            imgElement.setAttribute('src', item.data);
            countVisual++;
        });

        // --- RESPIROS Y LOGS ---
        // Pequeño respiro cada 10 elementos para no saturar el hilo principal
        if (i % 10 === 0 && i > 0) {
            console.log(`⏳ Restaurando... ${Math.round((i / ImagesLoaded.length) * 100)}%`);
            await new Promise(resolve => setTimeout(resolve, 50)); // Pausa de 50ms
        }
    }

    // --- APARTADO D: SINCRONIZACIÓN FINAL (CLONACIÓN DE MEMORIA) ---
    app.setState({
        allAssetsLoaded: true,
        assetsLoaded: app.state.assets.length,
        assets: [...app.state.assets] // Clonación necesaria para fijar los cambios
    }, () => {
        console.log("%c✅ PROCESO COMPLETADO", "color: #00ff00; font-weight: bold;");
        console.table({
            "Assets fijados en React": countMemory,
            "Iconos cambiados en UI": countVisual,
            "Total en JSON": ImagesLoaded.length
        });
    });

})();